package model

import (
	"testing"

	"github.com/sandbox-kit/kit/tooling/internal/spec"
)

func behaviorFixture(t *testing.T) (Behaviors, spec.Callable) {
	t.Helper()
	raw, err := spec.LoadBehaviors("../../../specs")
	if err != nil {
		t.Fatal(err)
	}
	contracts, err := CompileBehaviors(raw)
	if err != nil {
		t.Fatal(err)
	}
	return contracts, spec.Callable{
		ID: "provider_checks", Name: "validateProviderCreate", Behavior: "provider_checks", Fallible: true,
		Params: []spec.APISlot{{ID: "request", Name: "request", Type: spec.TypeRef{Ref: "request", Reference: true, Nullable: true}}},
	}
}

func TestBehaviorContractsPermitNativeNames(t *testing.T) {
	b, c := behaviorFixture(t)
	c.Name = "ValidateProvider"
	c.Params = append([]spec.APISlot{}, c.Params...)
	c.Params[0].Name = "options"
	if err := b.Validate(c, false); err != nil {
		t.Fatal(err)
	}
}

func TestBehaviorContractsRejectIncompatibleDeclarations(t *testing.T) {
	for _, tc := range []struct {
		name string
		edit func(*spec.Callable)
	}{
		{"missing request", func(c *spec.Callable) { c.Params = nil }},
		{"wrong type", func(c *spec.Callable) { c.Params[0].Type = spec.TypeRef{Builtin: "string"} }},
		{"wrong ID", func(c *spec.Callable) { c.Params[0].ID = "unrelated" }},
		{"missing failure", func(c *spec.Callable) { c.Fallible = false }},
		{"extra parameter", func(c *spec.Callable) {
			c.Params = append(c.Params, spec.APISlot{ID: "extra", Name: "extra", Type: spec.TypeRef{Builtin: "string"}})
		}},
		{"unknown behavior", func(c *spec.Callable) { c.Behavior = "arbitrary_execution" }},
	} {
		t.Run(tc.name, func(t *testing.T) {
			b, c := behaviorFixture(t)
			tc.edit(&c)
			if err := b.Validate(c, false); err == nil {
				t.Fatal("incompatible behavior accepted")
			}
		})
	}
}

package sandbox

import (
	"math"
	"regexp"
	"strings"

	"google.golang.org/protobuf/types/known/durationpb"
)

// imageReferencePattern matches portable container image references.
var imageReferencePattern = regexp.MustCompile(`^(?:[A-Za-z0-9](?:[A-Za-z0-9.-]*[A-Za-z0-9])?(?::[0-9]+)?/)?[a-z0-9]+(?:(?:[._]|__|-+)[a-z0-9]+)*(?:/[a-z0-9]+(?:(?:[._]|__|-+)[a-z0-9]+)*)*(?::[A-Za-z0-9_][A-Za-z0-9_.-]{0,127})?(?:@sha256:[a-fA-F0-9]{64})?$`)

// ValidateCreateOptions rejects CreateOptions values the shared contract cannot
// represent. A nil request is treated as omitted configuration. Account quotas
// stay with the provider.
//
// Portable rules are handwritten here and inventoried in specs/validation.yaml.
// They can move onto protobuf (Protovalidate) after remaining emitters are gone.
func ValidateCreateOptions(request *CreateOptions) error {
	if request == nil {
		return nil
	}
	if err := validateSandboxSource(request.Source, "source"); err != nil {
		return err
	}
	if err := validateRuntimeConfig(request.Runtime, "runtime"); err != nil {
		return err
	}
	if err := validateIsolationConfig(request.Isolation, "isolation"); err != nil {
		return err
	}
	if err := validateResources(request.Resources, "resources"); err != nil {
		return err
	}
	if err := validatePlacement(request.Placement, "placement"); err != nil {
		return err
	}
	if err := validateNetworkConfig(request.Network, "network"); err != nil {
		return err
	}
	if err := validateSecurityConfig(request.Security, "security"); err != nil {
		return err
	}
	if err := validateLifetimePolicy(request.Lifetime, "lifetime"); err != nil {
		return err
	}
	if err := validateProvisioningOptions(request.Provisioning, "provisioning"); err != nil {
		return err
	}
	if err := validateReadinessProbe(request.Readiness, "readiness"); err != nil {
		return err
	}
	return validateObservabilityConfig(request.Observability, "observability")
}

func validateSandboxSource(source *SandboxSource, path string) error {
	if source == nil {
		return nil
	}
	switch kind := source.Kind.(type) {
	case nil, *SandboxSource_ProviderDefault:
		return nil
	case *SandboxSource_Image:
		return validateImageSource(kind.Image, path+".image")
	case *SandboxSource_Snapshot:
		return validateSnapshotSource(kind.Snapshot, path+".snapshot")
	case *SandboxSource_WarmPool:
		return validateWarmPoolSource(kind.WarmPool, path+".warm_pool")
	default:
		return invalidCreate(path, "known_enum")
	}
}

func validateImageSource(source *ImageSource, path string) error {
	if source == nil {
		return invalidCreate(path, "required")
	}
	ref := source.GetReference()
	if strings.TrimSpace(ref) == "" {
		return invalidCreate(path+".reference", "nonblank")
	}
	if len(ref) > 512 || !imageReferencePattern.MatchString(ref) {
		return invalidCreate(path+".reference", "image_reference")
	}
	return nil
}

func validateSnapshotSource(source *SnapshotSource, path string) error {
	if source == nil {
		return invalidCreate(path, "required")
	}
	if strings.TrimSpace(source.GetReference()) == "" {
		return invalidCreate(path+".reference", "nonblank")
	}
	return knownEnum(path+".kind", int32(source.GetKind()), 0, 6)
}

func validateWarmPoolSource(source *WarmPoolSource, path string) error {
	if source == nil {
		return invalidCreate(path, "required")
	}
	if strings.TrimSpace(source.GetReference()) == "" {
		return invalidCreate(path+".reference", "nonblank")
	}
	return nil
}

func validateRuntimeConfig(config *RuntimeConfig, path string) error {
	if config == nil {
		return nil
	}
	if err := nonblankOptional(config.Language, path+".language"); err != nil {
		return err
	}
	if err := nonblankOptional(config.Version, path+".version"); err != nil {
		return err
	}
	if err := nonblankOptional(config.User, path+".user"); err != nil {
		return err
	}
	if err := nonblankOptional(config.WorkingDirectory, path+".working_directory"); err != nil {
		return err
	}
	return nonblankEach(config.Entrypoint, path+".entrypoint")
}

func validateIsolationConfig(config *IsolationConfig, path string) error {
	if config == nil {
		return nil
	}
	return knownEnum(path+".kind", int32(config.GetKind()), 0, 5)
}

func validateResources(resources *Resources, path string) error {
	if resources == nil {
		return nil
	}
	if resources.CpuCores != nil {
		value := resources.GetCpuCores()
		if math.IsNaN(value) || math.IsInf(value, 0) {
			return invalidCreate(path+".cpu_cores", "finite")
		}
		if !(value > 0) {
			return invalidCreate(path+".cpu_cores", "exclusive_minimum")
		}
	}
	if resources.CpuLimitCores != nil {
		value := resources.GetCpuLimitCores()
		if math.IsNaN(value) || math.IsInf(value, 0) {
			return invalidCreate(path+".cpu_limit_cores", "finite")
		}
		if value < 0 {
			return invalidCreate(path+".cpu_limit_cores", "minimum")
		}
	}
	if resources.MemoryMib != nil && !(resources.GetMemoryMib() > 0) {
		return invalidCreate(path+".memory_mib", "exclusive_minimum")
	}
	if resources.DiskMib != nil && !(resources.GetDiskMib() > 0) {
		return invalidCreate(path+".disk_mib", "exclusive_minimum")
	}
	if resources.GetCpuLimitCores() > 0 && resources.GetCpuLimitCores() < resources.GetCpuCores() {
		return invalidCreate(path+".cpu_limit_cores", "limit")
	}
	if resources.GetMemoryLimitMib() > 0 && resources.GetMemoryLimitMib() < resources.GetMemoryMib() {
		return invalidCreate(path+".memory_limit_mib", "limit")
	}
	if resources.GetCpuLimitCores() > 0 && resources.GetCpuCores() == 0 {
		return invalidCreate(path+".cpu_limit_cores", "requires_positive")
	}
	if resources.GetMemoryLimitMib() > 0 && resources.GetMemoryMib() == 0 {
		return invalidCreate(path+".memory_limit_mib", "requires_positive")
	}
	return nil
}

func validatePlacement(placement *Placement, path string) error {
	if placement == nil {
		return nil
	}
	return nonblankEach(placement.Regions, path+".regions")
}

func validateNetworkConfig(network *NetworkConfig, path string) error {
	if network == nil {
		return nil
	}
	if err := knownEnum(path+".egress", int32(network.GetEgress()), 0, 3); err != nil {
		return err
	}
	if err := nonblankOptional(network.LinkedSandbox, path+".linked_sandbox"); err != nil {
		return err
	}
	if err := nonblankOptional(network.ProxyReference, path+".proxy_reference"); err != nil {
		return err
	}
	if network.GetEgress() == EgressModeRestricted && network.OutboundCidrs == nil && network.OutboundDomains == nil {
		return invalidCreate(path+".outbound_cidrs,outbound_domains", "requires_any")
	}
	if network.GetEgress() == EgressModeBlockAll {
		if network.OutboundCidrs != nil || network.OutboundDomains != nil || network.InboundCidrs != nil ||
			network.LinkedSandbox != nil || len(network.Ports) > 0 || network.GetPrivateNetwork() {
			return invalidCreate(path+".outbound_cidrs,outbound_domains,private_network,linked_sandbox,inbound_cidrs,ports", "forbids")
		}
	}
	if network.GetEgress() == EgressModeAllowAll && (network.OutboundCidrs != nil || network.OutboundDomains != nil) {
		return invalidCreate(path+".outbound_cidrs,outbound_domains", "forbids")
	}
	for _, port := range network.Ports {
		if port == nil {
			return invalidCreate(path+".ports", "required")
		}
		if err := validatePortBinding(port, path+".ports"); err != nil {
			return err
		}
	}
	return nil
}

func validatePortBinding(port *PortBinding, path string) error {
	if port.Port != 0 {
		if port.GetPort() < 1 {
			return invalidCreate(path+".port", "minimum")
		}
		if port.GetPort() > 65535 {
			return invalidCreate(path+".port", "maximum")
		}
	}
	return knownEnum(path+".transport", int32(port.GetTransport()), 0, 3)
}

func validateSecurityConfig(security *SecurityConfig, path string) error {
	if security == nil {
		return nil
	}
	for _, secret := range security.Secrets {
		if secret == nil {
			return invalidCreate(path+".secrets", "required")
		}
		if err := validateSecretReference(secret, path+".secrets"); err != nil {
			return err
		}
	}
	return nil
}

func validateSecretReference(secret *SecretReference, path string) error {
	if strings.TrimSpace(secret.GetReference()) == "" {
		return invalidCreate(path+".reference", "nonblank")
	}
	if err := nonblankOptional(secret.EnvironmentVariable, path+".environment_variable"); err != nil {
		return err
	}
	return knownEnum(path+".injection", int32(secret.GetInjection()), 0, 2)
}

func validateLifetimePolicy(policy *LifetimePolicy, path string) error {
	if policy == nil {
		return nil
	}
	if err := nonNegativeDuration(policy.MaximumLifetime, path+".maximum_lifetime"); err != nil {
		return err
	}
	if err := validateAutomaticAction(policy.IdleTerminate, path+".idle_terminate"); err != nil {
		return err
	}
	if err := validateAutomaticAction(policy.IdleStop, path+".idle_stop"); err != nil {
		return err
	}
	if err := validateAutomaticAction(policy.IdlePause, path+".idle_pause"); err != nil {
		return err
	}
	if err := validateAutomaticAction(policy.StoppedArchive, path+".stopped_archive"); err != nil {
		return err
	}
	return validateAutomaticAction(policy.StoppedDelete, path+".stopped_delete")
}

func validateAutomaticAction(action *AutomaticAction, path string) error {
	if action == nil {
		return nil
	}
	if err := knownEnum(path+".mode", int32(action.GetMode()), 0, 2); err != nil {
		return err
	}
	if err := nonNegativeDuration(action.After, path+".after"); err != nil {
		return err
	}
	if action.GetMode() == PolicyModeAfter && action.After == nil {
		return invalidCreate(path+".after", "requires_any")
	}
	if action.GetMode() != PolicyModeAfter && action.After != nil {
		return invalidCreate(path+".after", "forbids")
	}
	return nil
}

func validateProvisioningOptions(options *ProvisioningOptions, path string) error {
	if options == nil {
		return nil
	}
	if err := nonNegativeDuration(options.Timeout, path+".timeout"); err != nil {
		return err
	}
	if err := nonNegativeDuration(options.QueueTimeout, path+".queue_timeout"); err != nil {
		return err
	}
	return knownEnum(path+".wait_for", int32(options.GetWaitFor()), 0, 4)
}

func validateReadinessProbe(probe *ReadinessProbe, path string) error {
	if probe == nil {
		return nil
	}
	switch check := probe.Check.(type) {
	case *ReadinessProbe_TcpPort:
		if check.TcpPort < 1 {
			return invalidCreate(path+".tcp_port", "minimum")
		}
		if check.TcpPort > 65535 {
			return invalidCreate(path+".tcp_port", "maximum")
		}
		return nil
	case *ReadinessProbe_Command:
		return validateCommandProbe(check.Command, path+".command")
	default:
		return invalidCreate(path+".tcp_port,command", "exactly_one")
	}
}

func validateCommandProbe(probe *CommandProbe, path string) error {
	if probe == nil {
		return invalidCreate(path, "required")
	}
	if len(probe.Argv) < 1 {
		return invalidCreate(path+".argv", "min_items")
	}
	return nil
}

func validateObservabilityConfig(config *ObservabilityConfig, path string) error {
	if config == nil {
		return nil
	}
	return nonblankOptional(config.TelemetryEndpoint, path+".telemetry_endpoint")
}

func invalidCreate(field, rule string) error {
	return NewError(ErrorInfo{Kind: ErrorKindInvalidArgument, Field: field, Rule: Value(rule), Message: "sandbox-kit: invalid configuration"}, nil)
}

func nonblankOptional(value *string, field string) error {
	if value != nil && strings.TrimSpace(*value) == "" {
		return invalidCreate(field, "nonblank")
	}
	return nil
}

func nonblankEach(values []string, field string) error {
	for _, value := range values {
		if strings.TrimSpace(value) == "" {
			return invalidCreate(field, "nonblank")
		}
	}
	return nil
}

func nonNegativeDuration(value *durationpb.Duration, field string) error {
	if value != nil && value.AsDuration() < 0 {
		return invalidCreate(field, "minimum")
	}
	return nil
}

func knownEnum(field string, value, min, max int32) error {
	if value < min || value > max {
		return invalidCreate(field, "known_enum")
	}
	return nil
}

package modal

import (
	"net/netip"
	"regexp"
	"strings"

	"github.com/sandbox-kit/kit/sdks/go/sandbox"
)

var providerEnvNamePattern = regexp.MustCompile(`^[A-Za-z_][A-Za-z0-9_]*$`)
var providerDomainPattern = regexp.MustCompile(`(?i)^(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)*[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.?$`)

// validateProviderCreate rejects creation settings this provider cannot honor.
// It runs before the native create call.
//
// Rules are inventoried in specs/providers/modal.yaml checks and kept in sync
// here by hand (no longer emitted).
func validateProviderCreate(request *sandbox.CreateOptions) error {
	if request == nil {
		return nil
	}
	if resources := request.Resources; resources != nil {
		if resources.CpuCores != nil && *resources.CpuCores < 0.125 {
			return providerCheckError(sandbox.ErrorKindInvalidArgument, sandbox.CreateFieldResourcesCpuCores, "resources.cpu_cores is outside supported values")
		}
		if resources.MemoryMib != nil && *resources.MemoryMib < 128 {
			return providerCheckError(sandbox.ErrorKindInvalidArgument, sandbox.CreateFieldResourcesMemoryMib, "resources.memory_mib is outside supported values")
		}
	}
	if request.Runtime != nil && request.Runtime.WorkingDirectory != nil {
		if !strings.HasPrefix(*request.Runtime.WorkingDirectory, "/") {
			return providerCheckError(sandbox.ErrorKindInvalidArgument, sandbox.CreateFieldRuntimeWorkingDirectory, "runtime.working_directory is outside supported values")
		}
	}
	if request.Placement != nil && request.Placement.Cloud != nil {
		cloud := *request.Placement.Cloud
		if cloud != "aws" && cloud != "gcp" && cloud != "oci" && cloud != "auto" {
			return providerCheckError(sandbox.ErrorKindUnsupported, sandbox.CreateFieldPlacementCloud, "placement.cloud is outside supported values")
		}
	}
	if network := request.Network; network != nil {
		if network.OutboundCidrs != nil {
			for _, value := range network.OutboundCidrs.Entries {
				if value != "" {
					if _, err := netip.ParsePrefix(value); err != nil {
						return providerCheckError(sandbox.ErrorKindInvalidArgument, sandbox.CreateFieldNetworkOutboundCidrsEntries, "network.outbound_cidrs.entries is outside supported values")
					}
				}
			}
		}
		if network.InboundCidrs != nil {
			for _, value := range network.InboundCidrs.Entries {
				if _, err := netip.ParsePrefix(value); err != nil {
					return providerCheckError(sandbox.ErrorKindInvalidArgument, sandbox.CreateFieldNetworkInboundCidrsEntries, "network.inbound_cidrs.entries is outside supported values")
				}
			}
		}
		if network.OutboundDomains != nil {
			for _, value := range network.OutboundDomains.Entries {
				if value == "" {
					continue
				}
				domain := strings.TrimPrefix(value, "*.")
				if !providerDomainPattern.MatchString(domain) || len(domain) > 253 {
					return providerCheckError(sandbox.ErrorKindInvalidArgument, sandbox.CreateFieldNetworkOutboundDomainsEntries, "network.outbound_domains.entries is outside supported values")
				}
			}
		}
	}
	for value := range request.Environment {
		if !providerEnvNamePattern.MatchString(value) {
			return providerCheckError(sandbox.ErrorKindInvalidArgument, sandbox.CreateFieldEnvironment, "environment is outside supported values")
		}
	}
	return nil
}

func providerCheckError(kind sandbox.ErrorKind, field, message string) error {
	return sandbox.NewError(sandbox.ErrorInfo{
		Kind:      kind,
		Provider:  "modal",
		Operation: "create",
		Field:     field,
		Message:   "sandbox-kit modal: " + message,
	}, nil)
}

package daytona

import (
	"net/netip"
	"net/url"
	"regexp"
	"strings"

	"github.com/sandbox-kit/kit/sdks/go/sandbox"
)

var providerEnvNamePattern = regexp.MustCompile(`^[A-Za-z_][A-Za-z0-9_]*$`)
var providerDomainPattern = regexp.MustCompile(`(?i)^(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)*[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.?$`)

// validateProviderCreate rejects creation settings this provider cannot honor.
// It runs before the native create call.
//
// Rules are inventoried in specs/providers/daytona.yaml checks and kept in sync
// here by hand (no longer emitted).
func validateProviderCreate(request *sandbox.CreateOptions) error {
	if request == nil {
		return nil
	}
	if request.Runtime != nil && request.Runtime.Language != nil {
		language := *request.Runtime.Language
		if language != "python" && language != "javascript" && language != "typescript" {
			return providerCheckError(sandbox.ErrorKindUnsupported, sandbox.CreateFieldRuntimeLanguage, "runtime.language is outside supported values")
		}
	}
	if network := request.Network; network != nil {
		if network.OutboundProxyUrl != nil {
			parsed, err := url.Parse(*network.OutboundProxyUrl)
			if err != nil || parsed.Host == "" || (parsed.Scheme != "http" && parsed.Scheme != "https") {
				return providerCheckError(sandbox.ErrorKindInvalidArgument, sandbox.CreateFieldNetworkOutboundProxyUrl, "network.outbound_proxy_url is outside supported values")
			}
		}
		if network.OutboundCidrs != nil {
			for _, value := range network.OutboundCidrs.Entries {
				if _, err := netip.ParsePrefix(value); err != nil {
					return providerCheckError(sandbox.ErrorKindInvalidArgument, sandbox.CreateFieldNetworkOutboundCidrsEntries, "network.outbound_cidrs.entries is outside supported values")
				}
			}
		}
		if network.OutboundDomains != nil {
			for _, value := range network.OutboundDomains.Entries {
				domain := strings.TrimPrefix(value, "*.")
				if !providerDomainPattern.MatchString(domain) || len(domain) > 253 {
					return providerCheckError(sandbox.ErrorKindInvalidArgument, sandbox.CreateFieldNetworkOutboundDomainsEntries, "network.outbound_domains.entries is outside supported values")
				}
			}
		}
	}
	if request.Security != nil {
		for _, item := range request.Security.Secrets {
			if item == nil {
				return sandbox.NewError(sandbox.ErrorInfo{
					Kind:      sandbox.ErrorKindInvalidArgument,
					Provider:  "daytona",
					Operation: "create",
					Field:     sandbox.CreateFieldSecuritySecretsEnvironmentVariable,
					Message:   "sandbox-kit: nil configuration entry",
				}, nil)
			}
			if item.EnvironmentVariable != nil && !providerEnvNamePattern.MatchString(*item.EnvironmentVariable) {
				return providerCheckError(sandbox.ErrorKindInvalidArgument, sandbox.CreateFieldSecuritySecretsEnvironmentVariable, "security.secrets.environment_variable is outside supported values")
			}
		}
	}
	if lifetime := request.Lifetime; lifetime != nil {
		if delayedPolicy(lifetime.IdleStop) && delayedPolicy(lifetime.IdlePause) {
			return incompatibleLifetime()
		}
		if delayedPolicy(lifetime.IdlePause) && lifetime.GetEphemeral() {
			return incompatibleLifetime()
		}
		if delayedPolicy(lifetime.IdlePause) && immediatePolicy(lifetime.StoppedDelete) {
			return incompatibleLifetime()
		}
		if delayedPolicy(lifetime.StoppedDelete) && lifetime.GetEphemeral() {
			return incompatibleLifetime()
		}
		if delayedPolicy(lifetime.StoppedArchive) && lifetime.GetEphemeral() {
			return incompatibleLifetime()
		}
	}
	return nil
}

func delayedPolicy(action *sandbox.AutomaticAction) bool {
	return action != nil && action.GetMode() == sandbox.PolicyModeAfter && action.After != nil && action.After.AsDuration() > 0
}

func immediatePolicy(action *sandbox.AutomaticAction) bool {
	return action != nil && action.GetMode() == sandbox.PolicyModeAfter && action.After != nil && action.After.AsDuration() == 0
}

func incompatibleLifetime() error {
	return sandbox.NewError(sandbox.ErrorInfo{
		Kind:      sandbox.ErrorKindInvalidArgument,
		Provider:  "daytona",
		Operation: "create",
		Field:     sandbox.CreateFieldLifetime,
		Message:   "sandbox-kit: incompatible lifetime policies",
	}, nil)
}

func providerCheckError(kind sandbox.ErrorKind, field, message string) error {
	return sandbox.NewError(sandbox.ErrorInfo{
		Kind:      kind,
		Provider:  "daytona",
		Operation: "create",
		Field:     field,
		Message:   "sandbox-kit daytona: " + message,
	}, nil)
}

import { ErrorKind, sandboxError, type CreateOptions } from "@sandbox-kit/sandbox";

// validateProviderCreate rejects creation settings this provider cannot honor.
// Rules are inventoried in specs/providers/modal.yaml checks.
export function validateProviderCreate(request: CreateOptions): void {
  const cpuCores = request.resources?.cpuCores;
  if (cpuCores !== undefined && cpuCores < 0.125) {
    fail(ErrorKind.InvalidArgument, "resources.cpuCores", "resources.cpu_cores is outside supported values");
  }
  const memoryMib = request.resources?.memoryMib;
  if (memoryMib !== undefined && memoryMib < BigInt("128")) {
    fail(ErrorKind.InvalidArgument, "resources.memoryMib", "resources.memory_mib is outside supported values");
  }
  const workingDirectory = request.runtime?.workingDirectory;
  if (workingDirectory !== undefined && !workingDirectory.startsWith("/")) {
    fail(ErrorKind.InvalidArgument, "runtime.workingDirectory", "runtime.working_directory is outside supported values");
  }
  const cloud = request.placement?.cloud;
  if (cloud !== undefined && cloud !== "aws" && cloud !== "gcp" && cloud !== "oci" && cloud !== "auto") {
    fail(ErrorKind.Unsupported, "placement.cloud", "placement.cloud is outside supported values");
  }
  for (const value of request.network?.outboundCidrs?.entries ?? []) {
    if (value !== "" && !validCidr(value)) {
      fail(ErrorKind.InvalidArgument, "network.outboundCidrs.entries", "network.outbound_cidrs.entries is outside supported values");
    }
  }
  for (const value of request.network?.inboundCidrs?.entries ?? []) {
    if (!validCidr(value)) {
      fail(ErrorKind.InvalidArgument, "network.inboundCidrs.entries", "network.inbound_cidrs.entries is outside supported values");
    }
  }
  for (const value of request.network?.outboundDomains?.entries ?? []) {
    if (value !== "" && !validDomain(value)) {
      fail(ErrorKind.InvalidArgument, "network.outboundDomains.entries", "network.outbound_domains.entries is outside supported values");
    }
  }
  for (const value of Object.keys(request.environment ?? {})) {
    if (!validEnvName(value)) {
      fail(ErrorKind.InvalidArgument, "environment", "environment is outside supported values");
    }
  }
}

function validEnvName(value: string): boolean {
  return /^[A-Za-z_][A-Za-z0-9_]*$/.test(value);
}

function validDomain(value: string): boolean {
  const domain = value.startsWith("*.") ? value.slice(2) : value;
  return domain.length <= 253 && /^(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)*[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.?$/i.test(domain);
}

function validCidr(value: string): boolean {
  const separator = value.lastIndexOf("/");
  if (separator <= 0) return false;
  const address = value.slice(0, separator);
  const prefix = Number(value.slice(separator + 1));
  if (!Number.isInteger(prefix)) return false;
  return address.includes(":")
    ? prefix >= 0 && prefix <= 128 && validIpv6(address)
    : prefix >= 0 && prefix <= 32 && validIpv4(address);
}

function validIpv4(value: string): boolean {
  const parts = value.split(".");
  return parts.length === 4 && parts.every((part) => /^(0|[1-9][0-9]{0,2})$/.test(part) && Number(part) <= 255);
}

function validIpv6(value: string): boolean {
  if ((value.match(/::/g)?.length ?? 0) > 1) return false;
  const halves = value.split("::");
  if (halves.length > 2) return false;
  const count = (part: string): number | undefined => {
    if (part === "") return 0;
    const groups = part.split(":");
    let total = 0;
    for (const group of groups) {
      if (/^[0-9a-f]{1,4}$/i.test(group)) total++;
      else if (validIpv4(group)) total += 2;
      else return undefined;
    }
    return total;
  };
  const left = count(halves[0] ?? "");
  const right = count(halves[1] ?? "");
  return left !== undefined && right !== undefined && (halves.length === 2 ? left + right < 8 : left === 8);
}

function fail(kind: ErrorKind, field: string, message: string): never {
  throw sandboxError({ kind, provider: "modal", operation: "create", field, message: "sandbox-kit modal: " + message });
}

import { durationMs } from "@bufbuild/protobuf/wkt";
import { ErrorKind, PolicyMode, sandboxError, type AutomaticAction, type CreateOptions } from "@sandbox-kit/sandbox";

// validateProviderCreate rejects creation settings this provider cannot honor.
// Rules are inventoried in specs/providers/daytona.yaml checks.
export function validateProviderCreate(request: CreateOptions): void {
  const language = request.runtime?.language;
  if (language !== undefined && language !== "python" && language !== "javascript" && language !== "typescript") {
    fail(ErrorKind.Unsupported, "runtime.language", "runtime.language is outside supported values");
  }
  const outboundProxyUrl = request.network?.outboundProxyUrl;
  if (outboundProxyUrl !== undefined && !validHttpUrl(outboundProxyUrl)) {
    fail(ErrorKind.InvalidArgument, "network.outboundProxyUrl", "network.outbound_proxy_url is outside supported values");
  }
  for (const value of request.network?.outboundCidrs?.entries ?? []) {
    if (!validCidr(value)) {
      fail(ErrorKind.InvalidArgument, "network.outboundCidrs.entries", "network.outbound_cidrs.entries is outside supported values");
    }
  }
  for (const value of request.network?.outboundDomains?.entries ?? []) {
    if (!validDomain(value)) {
      fail(ErrorKind.InvalidArgument, "network.outboundDomains.entries", "network.outbound_domains.entries is outside supported values");
    }
  }
  for (const item of request.security?.secrets ?? []) {
    const environmentVariable = item.environmentVariable;
    if (environmentVariable !== undefined && !validEnvName(environmentVariable)) {
      fail(ErrorKind.InvalidArgument, "security.secrets.environmentVariable", "security.secrets.environment_variable is outside supported values");
    }
  }
  if (delayed(request.lifetime?.idleStop) && delayed(request.lifetime?.idlePause)) {
    invalid("lifetime", "incompatible lifetime policies");
  }
  if (delayed(request.lifetime?.idlePause) && request.lifetime?.ephemeral === true) {
    invalid("lifetime", "incompatible lifetime policies");
  }
  if (delayed(request.lifetime?.idlePause) && immediate(request.lifetime?.stoppedDelete)) {
    invalid("lifetime", "incompatible lifetime policies");
  }
  if (delayed(request.lifetime?.stoppedDelete) && request.lifetime?.ephemeral === true) {
    invalid("lifetime", "incompatible lifetime policies");
  }
  if (delayed(request.lifetime?.stoppedArchive) && request.lifetime?.ephemeral === true) {
    invalid("lifetime", "incompatible lifetime policies");
  }
}

function delayed(policy: AutomaticAction | undefined): boolean {
  return (policy?.mode ?? PolicyMode.Default) === PolicyMode.After && policy?.after !== undefined && durationMs(policy.after) > 0;
}

function immediate(policy: AutomaticAction | undefined): boolean {
  return (policy?.mode ?? PolicyMode.Default) === PolicyMode.After && policy?.after !== undefined && durationMs(policy.after) === 0;
}

function validEnvName(value: string): boolean {
  return /^[A-Za-z_][A-Za-z0-9_]*$/.test(value);
}

function validHttpUrl(value: string): boolean {
  try {
    const parsed = new URL(value);
    return parsed.hostname !== "" && (parsed.protocol === "http:" || parsed.protocol === "https:");
  } catch {
    return false;
  }
}

function validDomain(value: string): boolean {
  const domain = value.startsWith("*.") ? value.slice(2) : value;
  return domain.length <= 253 && /^(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)*[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.?$/i.test(domain);
}

function validCidr(value: string): boolean {
