	t.Helper()
	contracts, err := CompileBehaviors(spec.Behaviors{
		Version: 1,
		Signatures: map[string]spec.BehaviorSignature{
			"request_mapping": {
				Owner:    "function",
				Fallible: true,
				Params: []spec.BehaviorSlot{
					{ID: "source", Type: spec.TypeRef{Ref: "source", Reference: true, Nullable: true}},
